// Shared helpers for the platform scripts (affected detection, dependency map). Plain Node, no dependencies, so it
// runs anywhere (primary, node-2, CI) without node_modules.
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");

/** `**` = any depth (incl. none), `*` = within one segment. Anchored at both ends. */
export function globToRe(glob) {
  let re = "";
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === "*" && glob[i + 1] === "*") {
      i++;
      if (glob[i + 1] === "/") { i++; re += "(?:.*/)?"; } else re += ".*";
    } else if (c === "*") re += "[^/]*";
    else re += c.replace(/[.+?^${}()|[\]\\]/g, "\\$&");
  }
  return new RegExp(`^${re}$`);
}

export function loadTargets(file = path.join(ROOT, "platform", "targets.json")) {
  const cfg = JSON.parse(readFileSync(file, "utf8"));
  const compile = (rules) => rules.map((r) => ({ ...r, re: globToRe(r.glob) }));
  return { targets: cfg.targets, feeds: compile(cfg.feeds), owners: compile(cfg.owners) };
}

export const firstMatch = (rules, file) => rules.find((r) => r.re.test(file)) ?? null;

/** Changed files -> { targets: sorted names, units: deploy units (embedded targets collapse into their host), byFile }. */
export function affected(files, cfg = loadTargets()) {
  const targets = new Set();
  const byFile = {};
  for (const f of files) {
    const rule = firstMatch(cfg.feeds, f);
    const ts = rule ? rule.targets : ["nxeon"];
    byFile[f] = ts;
    ts.forEach((t) => targets.add(t));
  }
  const units = new Set();
  for (const t of targets) {
    const def = cfg.targets[t];
    if (!def) throw new Error(`unknown target '${t}' in platform/targets.json`);
    units.add(def.mode === "embedded" ? def.embeddedIn : t);
  }
  return { targets: [...targets].sort(), units: [...units].sort(), byFile };
}

