#!/usr/bin/env node
// Which deploy targets does a change affect?   (docs/CYRUS-PLATFORM.md, rules in platform/targets.json)
//   node scripts/platform/affected.mjs                 # merge-base(main)..HEAD + uncommitted + untracked
//   node scripts/platform/affected.mjs --base <ref>    # <ref>..HEAD (+ working tree)
//   node scripts/platform/affected.mjs --files a b c   # explicit list (tests)
//   add --json for machine output, --units to print only deploy units (one per line), --explain for per-file rows
import { execFileSync } from "node:child_process";
import { ROOT, affected } from "./lib.mjs";

const args = process.argv.slice(2);
const flag = (n) => args.includes(n);
const opt = (n) => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : undefined; };
const git = (...a) => execFileSync("git", ["-C", ROOT, ...a], { encoding: "utf8" }).split("\n").filter(Boolean);

let files;
if (flag("--files")) files = args.slice(args.indexOf("--files") + 1).filter((a) => !a.startsWith("--"));
else {
  let base = opt("--base");
  if (!base) {
    for (const ref of ["main", "origin/main"]) {
      try { base = git("merge-base", "HEAD", ref)[0]; break; } catch { /* try next */ }
    }
  }
  if (!base) { console.error("affected: no --base and no main branch to compare with"); process.exit(2); }
  files = [...new Set([
    ...git("diff", "--name-only", `${base}...HEAD`),
    ...git("diff", "--name-only", "HEAD"),
    ...git("ls-files", "--others", "--exclude-standard"),
  ])].sort();
}

const res = affected(files);
if (flag("--json")) console.log(JSON.stringify({ files: files.length, ...res }, null, 2));
else if (flag("--units")) res.units.forEach((u) => console.log(u));
else {
  console.log(`${files.length} changed file(s)`);
  console.log(`targets: ${res.targets.join(" ") || "(none)"}`);
  console.log(`deploy units: ${res.units.join(" ") || "(none)"}`);
  if (flag("--explain")) for (const [f, ts] of Object.entries(res.byFile)) console.log(`  ${f} -> ${ts.join(",") || "-"}`);
}

