#!/usr/bin/env node
// Dependency map for the extraction: where every Cyrus file moves (platform/targets.json "owners") and what it still
// imports from Nxeon. Writes docs/cyrus-platform-depmap.md (+ .json with --json). Read-only over the source tree.
//   node scripts/platform/depmap.mjs [--check]   (--check: exit 1 if the committed map is stale)
import { readFileSync, readdirSync, statSync, writeFileSync, existsSync } from "node:fs";
import path from "node:path";
import { ROOT, loadTargets, firstMatch } from "./lib.mjs";

const cfg = loadTargets();
const SKIP = new Set(["node_modules", ".next", ".git", "apps", "public", "data"]);
const IMPORT_RE = /(?:\bfrom|\bimport|\brequire)\s*\(?\s*["']([^"']+)["']/g;

function walk(dir, out = []) {
  for (const n of readdirSync(dir)) {
    if (SKIP.has(n)) continue;
    const p = path.join(dir, n);
    const st = statSync(p);
    if (st.isDirectory()) walk(p, out);
    else if (/\.(ts|tsx|mjs)$/.test(n) && !n.endsWith(".d.ts")) out.push(path.relative(ROOT, p).split(path.sep).join("/"));
  }
  return out;
}
function resolve(fromFile, spec) {
  let abs;
  if (spec.startsWith(".")) abs = path.resolve(ROOT, path.dirname(fromFile), spec);
  else if (spec.startsWith("@/")) abs = path.join(ROOT, spec.slice(2));
  else return null;
  let rel = path.relative(ROOT, abs).split(path.sep).join("/");
  for (const ext of ["", ".ts", ".tsx", "/index.ts", "/index.tsx"]) if (existsSync(path.join(ROOT, rel + ext)) && statSync(path.join(ROOT, rel + ext)).isFile()) return rel + ext;
  return rel;
}

const all = walk(ROOT);
const home = (f) => firstMatch(cfg.owners, f)?.to ?? null;
const groups = {};
const reverse = {}; // Nxeon file -> cyrus homes it imports
for (const f of all) {
  const h = home(f);
  const src = readFileSync(path.join(ROOT, f), "utf8");
  const imports = [...src.matchAll(IMPORT_RE)].map((m) => resolve(f, m[1])).filter(Boolean);
  if (h) {
    const g = (groups[h] ??= { files: 0, lines: 0, nxeonImports: {}, cyrusImports: 0 });
    g.files++;
    g.lines += src.split("\n").length;
    for (const t of imports) {
      if (home(t)) { g.cyrusImports++; continue; }
      if (t.startsWith("node_modules")) continue;
      g.nxeonImports[t] = (g.nxeonImports[t] ?? 0) + 1;
    }
  } else {
    for (const t of imports) {
      const th = home(t);
      if (th) (reverse[f] ??= new Set()).add(th);
    }
  }
}

const rows = Object.entries(groups).sort((a, b) => b[1].files - a[1].files);
const md = [
  "# Cyrus extraction: dependency map (generated)",
  "",
  "Generated by `node scripts/platform/depmap.mjs` from `platform/targets.json` owners. Do not edit by hand. Plan: docs/CYRUS-PLATFORM.md.",
  "",
  "## Where each group moves",
  "",
  "| Future home | files | lines | imports of Nxeon internals | distinct Nxeon modules | top Nxeon modules |",
  "|---|---:|---:|---:|---:|---|",
  ...rows.map(([h, g]) => {
    const n = Object.entries(g.nxeonImports).sort((a, b) => b[1] - a[1]);
    const total = n.reduce((s, [, c]) => s + c, 0);
    return `| ${h} | ${g.files} | ${g.lines} | ${total} | ${n.length} | ${n.slice(0, 6).map(([m, c]) => `\`${m}\` (${c})`).join(", ")} |`;
  }),
  "",
  "## Nxeon files that import Cyrus code (they keep working through packages after the move)",
  "",
  `${Object.keys(reverse).length} Nxeon files. By area:`,
  "",
  "| Nxeon area | files | imports into |",
  "|---|---:|---|",
  ...Object.entries(Object.entries(reverse).reduce((acc, [f, hs]) => {
    const area = f.split("/").slice(0, 2).join("/");
    const a = (acc[area] ??= { n: 0, homes: new Set() });
    a.n++; hs.forEach((h) => a.homes.add(h.split(" ")[0]));
    return acc;
  }, {})).sort((a, b) => b[1].n - a[1].n).map(([a, v]) => `| ${a} | ${v.n} | ${[...v.homes].sort().join(", ")} |`),
  "",
].join("\n");

const out = path.join(ROOT, "docs", "cyrus-platform-depmap.md");
if (process.argv.includes("--check")) {
  const cur = existsSync(out) ? readFileSync(out, "utf8") : "";
  if (cur !== md) { console.error("docs/cyrus-platform-depmap.md is stale: run node scripts/platform/depmap.mjs"); process.exit(1); }
  console.log("depmap up to date");
} else {
  writeFileSync(out, md);
  if (process.argv.includes("--json")) writeFileSync(out.replace(/\.md$/, ".json"), JSON.stringify({ groups, reverse: Object.fromEntries(Object.entries(reverse).map(([k, v]) => [k, [...v]])) }, null, 2));
  console.log(`wrote ${path.relative(ROOT, out)}: ${rows.length} groups, ${Object.keys(reverse).length} Nxeon importers`);
}

