import { execFileSync, spawnSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, lstatSync, readlinkSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const ROOT = path.resolve(__dirname, "..");
type Lib = { affected(files: string[]): { targets: string[]; units: string[] }; globToRe(g: string): RegExp };
const lib = (): Promise<Lib> => import(path.join(ROOT, "scripts/platform/lib.mjs"));

describe("platform: affected targets", () => {
  it("globs: ** spans segments, * stays in one", async () => {
    const { globToRe } = await lib();
    assert.ok(globToRe("lib/cyrus/**").test("lib/cyrus/a/b.ts"));
    assert.ok(globToRe("app/admin/cyrus*/**").test("app/admin/cyrus-tokens/page.tsx"));
    assert.ok(!globToRe("*.md").test("docs/x.md"));
    assert.ok(globToRe("**").test("anything/at/all"));
  });
  it("maps changes to targets and collapses embedded targets into nxeon", async () => {
    const { affected } = await lib();
    assert.deepEqual(affected(["apps/cyrus-site/src/index.html"]), { targets: ["site"], units: ["site"], byFile: { "apps/cyrus-site/src/index.html": ["site"] } });
    const c = affected(["lib/cyrus/engine/x.ts"]);
    assert.deepEqual(c.targets, ["cyrus", "cyrus-admin", "nxeon"]);
    assert.deepEqual(c.units, ["nxeon"]);
    assert.deepEqual(affected(["app/billing/page.tsx"]).targets, ["nxeon"]);
    assert.deepEqual(affected(["test/cyrus-foo.test.ts", "scripts/ship"]).units, ["nxeon"]);
    assert.deepEqual(affected(["scripts/ship", "docs/../README.md".replace("docs/../", "")]).targets, []);
    assert.deepEqual(affected(["services/modbuilder/x.js"]).units.sort(), ["modbuilder", "nxeon"]);
  });
});

describe("platform: cyrus.my publish (temp docroot)", () => {
  it("first publish keeps the legacy dir as rollback, swaps atomically, rolls back on a failed health check", () => {
    const dir = mkdtempSync(path.join(tmpdir(), "cyrus-site-"));
    try {
      const live = path.join(dir, "live"), rel = path.join(dir, "rel");
      mkdirSync(live); writeFileSync(path.join(live, "index.html"), "legacy");
      const env = { ...process.env, CYRUS_SITE_LIVE: live, CYRUS_SITE_RELEASES: rel, CYRUS_SITE_KEEP: "3" };
      const sh = (...a: string[]) => spawnSync("bash", [path.join(ROOT, "apps/cyrus-site/publish.sh"), ...a], { env, encoding: "utf8" });
      assert.equal(sh("publish").status, 0, "dry run");
      assert.ok(!lstatSync(live).isSymbolicLink(), "dry run changes nothing");
      const r = sh("publish", "--go");
      assert.equal(r.status, 0, r.stderr);
      assert.ok(lstatSync(live).isSymbolicLink());
      assert.match(readFileSync(path.join(live, "index.html"), "utf8"), /<html/i);
      const first = readlinkSync(live);
      const bad = spawnSync("bash", [path.join(ROOT, "apps/cyrus-site/publish.sh"), "publish", "--go"], { env: { ...env, CYRUS_SITE_HEALTH_URL: "http://127.0.0.1:9/" }, encoding: "utf8" });
      assert.notEqual(bad.status, 0);
      assert.equal(readlinkSync(live), first, "failed health check rolled back");
      assert.equal(sh("rollback", "--go").status, 0);
      assert.equal(readFileSync(path.join(live, "index.html"), "utf8"), "legacy");
    } finally { rmSync(dir, { recursive: true, force: true }); }
  });
  it("site check passes on the committed source", () => {
    execFileSync("bash", [path.join(ROOT, "apps/cyrus-site/publish.sh"), "check"], { encoding: "utf8" });
  });
});

