describe("platform: promote-cyrus.sh", () => {
  const script = path.join(ROOT, "scripts/promote-cyrus.sh");
  it("dry run against the production spec prints the plan and touches nothing", () => {
    const r = spawnSync("bash", [script, "--env", "production", "--dry-run"], { encoding: "utf8" });
    assert.equal(r.status, 0, r.stderr);
    assert.match(r.stdout, /would require staging https:\/\/staging\.cyrus\.my/);
    assert.match(r.stdout, /DRY RUN: nothing ran/);
  });
  it("refuses a real run while Cyrus is embedded", () => {
    const r = spawnSync("bash", [script, "--env", "staging"], { encoding: "utf8" });
    assert.notEqual(r.status, 0);
    assert.match(r.stderr, /still embedded/);
  });
  it("full pipeline on a throwaway local host: smoke gate, cutover, auto-rollback", () => {
    const dir = mkdtempSync(path.join(tmpdir(), "cyrus-promote-"));
    const port = 20000 + Math.floor(Math.random() * 20000);
    const commit = execFileSync("git", ["-C", ROOT, "rev-parse", "HEAD"], { encoding: "utf8" }).trim();
    // fake.sh build|start|stop|restart: a "release" is a static dir with /api/cyrus/health naming a commit.
    const fake = path.join(dir, "fake.sh");
    writeFileSync(fake, `#!/bin/bash
set -e; D=${JSON.stringify(dir)}
serve() { cd "$2" && nohup python3 -m http.server "$1" --bind 127.0.0.1 >/dev/null 2>&1 </dev/null & echo $! > "$D/pid.$1"; }
stop() { [ -f "$D/pid.$1" ] && kill "$(cat "$D/pid.$1")" 2>/dev/null; rm -f "$D/pid.$1"; sleep 0.3; true; }
case "$1" in
  build) m=$D/b.$$; mkdir -p $m/api/cyrus; echo ok > $m/index.html
         printf '{"ok":true,"commit":"%s"}' "\${FAKE_COMMIT:-$3}" > $m/api/cyrus/health
         [ -n "\${FAKE_BAD_LIVE:-}" ] && touch $m/BAD; tar -czf $D/art.tgz -C $m .; echo $D/art.tgz ;;
  side) serve "$PORT" "$RELEASE" ;;
  stopside) stop "$PORT" ;;
  restart) stop ${port}; [ -e "$CYRUS_ROOT/current/BAD" ] && exit 0; serve ${port} "$CYRUS_ROOT/current" ;;
esac
`);
    const envFile = path.join(dir, "sim.env");
    writeFileSync(envFile, [
      "CYRUS_DEPLOY_HOST=local", `CYRUS_ROOT=${dir}/host`, `CYRUS_PUBLIC_URL=http://127.0.0.1:${port}`, `CYRUS_WEB_PORT=${port}`,
      `CYRUS_SMOKE_PORT=${port + 1}`, `CYRUS_BUILD_CMD="bash ${fake} build"`, `CYRUS_START_SIDE="bash ${fake} side"`,
      `CYRUS_STOP_SIDE="bash ${fake} stopside"`, `CYRUS_RESTART_WEB="bash ${fake} restart"`, "CYRUS_WAIT_SECS=6", "CYRUS_KEEP_RELEASES=2", "",
    ].join("\n"));
    const run = (extra: Record<string, string> = {}) => spawnSync("bash", [script, "--env", "staging"],
      { encoding: "utf8", env: { ...process.env, CYRUS_ENV_FILE: envFile, CYRUS_ALLOW_EMBEDDED: "1", ...extra }, timeout: 60_000 });
    const health = () => { try { return execFileSync("curl", ["-s", "--max-time", "3", `http://127.0.0.1:${port}/api/cyrus/health`], { encoding: "utf8" }); } catch { return ""; } };
    try {
      // dirty worktrees refuse a real run; the simulation only checks the pipeline, so ignore that rule here
      const clean = execFileSync("git", ["-C", ROOT, "status", "--porcelain", "--untracked-files=no"], { encoding: "utf8" }) === "";
      if (!clean) return;
      const ok = run();
      assert.equal(ok.status, 0, ok.stdout + ok.stderr);
      assert.match(health(), new RegExp(commit.slice(0, 10)));
      const first = readlinkSync(path.join(dir, "host", "current"));
      const smokeFail = run({ FAKE_COMMIT: "0000000000" });
      assert.notEqual(smokeFail.status, 0);
      assert.match(smokeFail.stderr, /side-port smoke/);
      assert.equal(readlinkSync(path.join(dir, "host", "current")), first, "smoke failure never touches live");
      const badLive = run({ FAKE_BAD_LIVE: "1" });
      assert.notEqual(badLive.status, 0);
      assert.match(badLive.stderr, /AUTO-ROLLBACK/);
      assert.equal(readlinkSync(path.join(dir, "host", "current")), first, "rolled back");
      assert.match(health(), new RegExp(commit.slice(0, 10)));
    } finally {
      spawnSync("bash", [fake, "restart"], { env: { ...process.env, CYRUS_ROOT: path.join(dir, "none") } });
      for (const p of [port, port + 1]) spawnSync("bash", ["-c", `[ -f ${dir}/pid.${p} ] && kill $(cat ${dir}/pid.${p}) || true`]);
      rmSync(dir, { recursive: true, force: true });
    }
  });
});
EOF
timeout 200 /opt/nxeon/node_modules/.bin/tsx --test test/platform-scripts.test.ts 2>&1 | grep -E '^# (pass|fail)|not ok|Error|assert' | head -20

