// Cloudflare groundwork (docs/CYRUS-PLATFORM.md section 3): the app keeps the visitor's IP once nginx restores it
// from CF-Connecting-IP. Runs scripts/cloudflare/test-realip.sh (throwaway nginx + echo backend) when nginx exists,
// then feeds the headers the app would really receive into the one client-IP function.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import path from "node:path";
import { clientIp } from "../lib/rate-limit";

const ROOT = path.resolve(__dirname, "..");
const H = (o: Record<string, string>) => new Headers(o);

describe("cloudflare real IP", () => {
  it("clientIp takes nginx's hop for CF-shaped chains and never the client-written entries", () => {
    // after real_ip: CF appended the visitor, nginx appended $remote_addr (= the restored visitor)
    assert.equal(clientIp(H({ "x-forwarded-for": "6.6.6.6, 203.0.113.7, 203.0.113.7", "x-real-ip": "203.0.113.7" })), "203.0.113.7");
    // direct-to-origin with forged headers: nginx's hop is the attacker's real address
    assert.equal(clientIp(H({ "x-forwarded-for": "198.51.100.9, 127.0.0.1", "x-real-ip": "127.0.0.1", "cf-connecting-ip": "198.51.100.9" })), "127.0.0.1");
    assert.equal(clientIp(H({ "x-real-ip": "2001:db8::5" })), "2001:db8::5");
  });
  it("generated range file is well-formed and trusts only CF-Connecting-IP", () => {
    const conf = readFileSync(path.join(ROOT, "deploy/cloudflare/nginx/cloudflare-realip.conf"), "utf8");
    const ranges = conf.split("\n").filter((l) => l.startsWith("set_real_ip_from "));
    assert.ok(ranges.length >= 15, `${ranges.length} ranges`);
    for (const r of ranges) assert.match(r, /^set_real_ip_from [0-9a-f.:]+\/\d{1,3};$/);
    assert.match(conf, /^real_ip_header CF-Connecting-IP;$/m);
    assert.doesNotMatch(conf, /set_real_ip_from (0\.0\.0\.0|::)\/0/);
  });
  it("throwaway nginx simulation: restored for edges, ignored for direct callers", (t) => {
    const r = spawnSync("bash", [path.join(ROOT, "scripts/cloudflare/test-realip.sh"), "--json"], { encoding: "utf8", timeout: 30_000 });
    if (r.status === 77) return t.skip("nginx not installed here");
    assert.equal(r.status, 0, r.stdout + r.stderr);
    const j = JSON.parse(r.stdout.trim().split("\n").find((l) => l.startsWith("{"))!);
    assert.equal(clientIp(H(j.edge)), "203.0.113.7");
    assert.equal(clientIp(H(j.direct)), "127.0.0.1");
    assert.equal(clientIp(H(j.edgeV6)), "2001:db8::5");
  });
});
EOF
timeout 60 /opt/nxeon/node_modules/.bin/tsx --test test/cloudflare-realip.test.ts 2>&1 | grep -E '^# (pass|fail|skip)|not ok'

