// can replace `post` later without touching call sites.
type Ctx = Record<string, string | number | boolean | null | undefined>;
const SECRET = /(postgres(?:ql)?:\/\/[^:\s]+:)[^@\s]+@|((?:key|token|secret|password|authorization)["'=:\s]+)[^\s"',;]+|(sk-[A-Za-z0-9_-]{8})[A-Za-z0-9_-]+/gi;
export const scrub = (s: string) => s.replace(SECRET, (_m, a, b, c) => `${a ?? b ?? c}***${a ? "@" : ""}`).slice(0, 1500);

const seen = new Map<string, number>();
let windowStart = 0, sentInWindow = 0;

export function reportCyrusError(err: unknown, ctx: Ctx = {}, deps: { post?: (url: string, body: string) => Promise<unknown>; env?: Record<string, string | undefined>; now?: number } = {}): { posted: boolean } {
