// Cyrus observability (docs/CYRUS-PLATFORM.md section 5): health probe semantics and the error hook's scrub/dedupe.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { cyrusHealth, releaseCommit } from "../lib/cyrus/observability/health";
import { reportCyrusError, scrub } from "../lib/cyrus/observability/errors";

