    const deg = await cyrusHealth({ pingDb: async () => 1, pingBuildService: async () => false, commit: null });
    assert.equal(deg.ok, true); assert.equal(deg.status, "degraded");
    const down = await cyrusHealth({ pingDb: () => new Promise(() => {}), pingBuildService: null, commit: null, timeoutMs: 50 });
    assert.equal(down.ok, false); assert.equal(down.status, "down"); assert.equal(down.checks.buildService, "unconfigured");
    assert.equal(releaseCommit({ CYRUS_RELEASE_COMMIT: " 0123456789abcdef " }), "0123456789abcdef");
