      assert.equal(reportCyrusError(new Error("boom"), { where: "t" }, { env: {}, post }).posted, false);
      assert.equal(reportCyrusError(new Error("boom"), { where: "t" }, { env, post, now: 1_000_000 }).posted, true);
      assert.equal(reportCyrusError(new Error("boom"), { where: "t" }, { env, post, now: 1_000_500 }).posted, false);
      assert.equal(reportCyrusError(new Error("boom"), { where: "t" }, { env, post, now: 1_700_000 }).posted, true);
      assert.equal(reportCyrusError("not an error", {}, { env, post, now: 1_700_001 }).posted, true);
    } finally { console.error = orig; }
  });
});
EOF
